import sys,json
from pathlib import Path
sys.path.insert(0,'/private/tmp/ceo-skill-source-bindings')
from app.agent_cli import build_role_server
from mcp.server.fastmcp import FastMCP
from mcp.types import ToolAnnotations
root=Path(__file__).parent;role=sys.argv[1];arm=sys.argv[2]
registered=build_role_server(role,task_id=7,db_path=root/'reader.sqlite3',execution_generation='first')
mcp=FastMCP('agent_cli');ann=ToolAnnotations(readOnlyHint=True,destructiveHint=False,idempotentHint=True,openWorldHint=False)
def log(name,args,result):
 with (root/f'{role}.{arm}.calls.jsonl').open('a') as f:f.write(json.dumps({'name':name,'args':args,'result':result},ensure_ascii=False)+'\n')
 return result
@mcp.tool(annotations=ann)
def read_task_skill(name:str)->dict[str,object]:
 return log('read_task_skill',{'name':name},registered._tool_manager.get_tool('read_task_skill').fn(name=name))
@mcp.tool(annotations=ann)
def read_skill(path:str|None=None,name:str|None=None)->dict[str,object]:
 return log('read_skill',{'path':path,'name':name},registered._tool_manager.get_tool('read_skill').fn(path=path,name=name))
@mcp.tool(annotations=ann)
def read_text_file(path:str)->dict[str,object]:
 return log('read_text_file',{'path':path},registered._tool_manager.get_tool('read_text_file').fn(path=path))
@mcp.tool(annotations=ann)
def read_dingtalk_messages(conversation_id:str,title:str='',single_chat:bool=False,limit:int=50)->dict[str,object]:
 if conversation_id!='cid-closed':raise ValueError('unknown anonymous conversation')
 return log('read_dingtalk_messages',{'conversation_id':conversation_id,'title':title,'single_chat':single_chat,'limit':limit},json.loads((root/'snapshot.json').read_text()))
if __name__=='__main__':mcp.run(transport='stdio')
